3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Single source of truth for an owner's <em>identity</em>. All duplicate detection on the create
9	 * endpoint is expressed through one derived {@code identityKey}:
10	 *
11	 * <pre>identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId</pre>
12	 *
13	 * <p>A new owner is a duplicate (409) only when its whole {@code identityKey} equals an existing
14	 * owner's — see {@link CheckIdentityUnique}. Because the normalized telephone is part of the key,
15	 * two members of the same household (same {@code householdId}) with different telephones have
16	 * different keys and are both allowed; only an exact full-key match collides.
17	 *
18	 * <p>The {@code householdId} is the stable identifier shared by owners living in the same household
19	 * (same normalized last name and postcode): the first 12 upper-cased hex characters of the SHA-256 of
20	 * {@code '<lastName>|<postcode>'}. {@link AssignHouseholdId} assigns it and {@link OwnerMapper} returns
21	 * both it and the {@code identityKey}.
22	 */
23	public final class OwnerIdentity {
24	
25	    private OwnerIdentity() {
26	    }
27	
28	    /**
29	     * The shared {@code householdId} derived from the last name and postcode: the first 12 upper-cased
30	     * hex characters of SHA-256 of {@code '<lastName>|<postcode>'}, with the last name normalized
31	     * (lower-cased, runs of whitespace collapsed, trimmed) and a null/blank postcode contributing the
32	     * empty string. Because it is a pure function of {@code (lastName, postcode)}, two owners sharing
33	     * both deterministically receive the same value — they are, by definition, the same household.
34	     */
35	    public static String householdId(String lastName, String postcode) {
36	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode.trim());
37	        return shaHex(key, 12);
38	    }
39	
40	    /**
41	     * The derived {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) + '|' +
42	     * householdId}. A blank/absent email contributes the empty string.
43	     */
44	    public static String identityKey(String telephone, String email, String householdId) {
45	        String tel = telephone == null ? "" : telephone;
46	        String em = (email == null || email.isBlank()) ? "" : email;
47	        String hh = householdId == null ? "" : householdId;
48	        return tel + "|" + em + "|" + hh;
49	    }
50	
51	    /** Lower-cases and collapses runs of whitespace to a single space, trimmed. Used for last name. */
52	    private static String normalizeName(String value) {
53	        if (value == null) {
54	            return "";
55	        }
56	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
57	    }
58	
59	    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
60	    private static String shaHex(String value, int n) {
61	        try {
62	            byte[] digest = MessageDigest.getInstance("SHA-256")
63	                    .digest(value.getBytes(StandardCharsets.UTF_8));
64	            StringBuilder sb = new StringBuilder(digest.length * 2);
65	            for (byte b : digest) {
66	                sb.append(String.format("%02X", b));
67	            }
68	            return sb.substring(0, n);
69	        }
70	        catch (NoSuchAlgorithmException e) {
71	            throw new IllegalStateException("SHA-256 not available", e);
72	        }
73	    }
74	}
